//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration with a bounded exponential delay policy.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self { max_attempts, base_delay_ms, max_delay_ms }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn new_sets_policy_values() {
        assert_eq!(RetryConfig::new(4, 25, 100), RetryConfig {
            max_attempts: 4,
            base_delay_ms: 25,
            max_delay_ms: 100,
        });
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn classifies_error_variants() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let attempts = config.max_attempts.max(1);

    for attempt in 0..attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt + 1 == attempts => {
                return Err(error);
            }
            Err(_) => {
                let multiplier = 1u64.checked_shl(attempt).unwrap_or(u64::MAX);
                let delay = config
                    .base_delay_ms
                    .checked_mul(multiplier)
                    .unwrap_or(u64::MAX)
                    .min(config.max_delay_ms);
                sleeper.sleep_ms(delay);
            }
        }
    }

    unreachable!("the retry loop always returns from an attempt")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig::new(5, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_are_returned_without_retry() {
        let config = RetryConfig::new(5, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let config = RetryConfig::new(3, 1, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let config = RetryConfig::new(0, 1, 100);
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config, &mut sleeper, || Err(RetryError::Transient("down".into())));

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert!(sleeper.sleeps.is_empty());
    }
}

